//! Malay inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Malay dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Degree {
    Comparative,
    Superlative,
}

impl Degree {
    pub const ALL: [Self; 2] = [Self::Comparative, Self::Superlative];
}

/// Settings for systematic choices. `Malay::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Malay {
    pub options: Options,
}

impl Malay {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// The active verb.
    pub fn verb_active_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(0);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The active verb. The best candidate; the word itself if nothing is known.
    pub fn verb_active(&self, word: &str) -> String {
        best(self.verb_active_scored(word), word)
    }

    /// The passive verb.
    pub fn verb_passive_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(1);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The passive verb. The best candidate; the word itself if nothing is known.
    pub fn verb_passive(&self, word: &str) -> String {
        best(self.verb_passive_scored(word), word)
    }

    /// Dictionary spelling of a verb (with stress marks where the data has them).
    pub fn verb_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adj form.
    pub fn adj_scored(&self, word: &str, degree: Degree) -> Scored<String> {
        let cell: Option<u32> = match (degree,) {
            (Degree::Comparative,) => Some(0),
            (Degree::Superlative,) => Some(1),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form. The best candidate; the word itself if nothing is known.
    pub fn adj(&self, word: &str, degree: Degree) -> String {
        best(self.adj_scored(word, degree), word)
    }

    /// Dictionary spelling of a adj (with stress marks where the data has them).
    pub fn adj_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

}

/// The active verb.
pub fn verb_active(word: &str) -> String {
    Malay::default().verb_active(word)
}

/// The active verb. Every candidate with its confidence, best first.
pub fn verb_active_scored(word: &str) -> Scored<String> {
    Malay::default().verb_active_scored(word)
}

/// The passive verb.
pub fn verb_passive(word: &str) -> String {
    Malay::default().verb_passive(word)
}

/// The passive verb. Every candidate with its confidence, best first.
pub fn verb_passive_scored(word: &str) -> Scored<String> {
    Malay::default().verb_passive_scored(word)
}

/// Dictionary spelling of a verb.
pub fn verb_lemma(word: &str) -> String {
    Malay::default().verb_lemma(word)
}

/// A adj form.
pub fn adj(word: &str, degree: Degree) -> String {
    Malay::default().adj(word, degree)
}

/// A adj form. Every candidate with its confidence, best first.
pub fn adj_scored(word: &str, degree: Degree) -> Scored<String> {
    Malay::default().adj_scored(word, degree)
}

/// Dictionary spelling of a adj.
pub fn adj_lemma(word: &str) -> String {
    Malay::default().adj_lemma(word)
}

/// One reading of a form: its part of speech, lemma, and every cell it fills
/// for that lemma (empty when it is only the dictionary form).
#[derive(Clone, Debug, PartialEq)]
pub struct Analysis {
    pub pos: &'static str,
    pub lemma: String,
    pub cells: Vec<&'static str>,
}

/// Which lemma and cell a form could be, best first. Works for unknown words too.
pub fn analyze(word: &str) -> Scored<Analysis> {
    let Some(m) = model() else { return Vec::new() };
    m.analyze(word)
        .into_iter()
        .filter_map(|(a, p)| {
            let pos = m.pos.get(a.pos)?;
            let cells = a.cells.iter().filter_map(|&c| pos.cells.get(c as usize).map(String::as_str)).collect();
            Some((Analysis { pos: pos.name.as_str(), lemma: a.lemma, cells }, p))
        })
        .collect()
}

/// Inflect by names, e.g. `inflect("noun", "GenitivePlural", word)`.
pub fn inflect(pos: &str, cell: &str, word: &str) -> Scored<String> {
    let Some(m) = model() else { return Vec::new() };
    let Some(pi) = m.pos.iter().position(|p| p.name == pos) else { return Vec::new() };
    let Some(ci) = m.pos.get(pi).and_then(|p| p.cells.iter().position(|c| c == cell)) else { return Vec::new() };
    m.inflect(pi, ci as u32, word, Options::default())
}

// ---- hand-written, from the Malay config ----

/// A noun's plural: the (first) word reduplicated, as in buku-buku,
/// rumah-rumah sakit.
pub fn noun_plural(word: &str) -> String {
    let word = word.trim();
    match word.split_once(' ') {
        Some((head, rest)) => format!("{head}-{head} {rest}"),
        None => format!("{word}-{word}"),
    }
}
